from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
speed = 250
left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right = Motor(Port.E, Direction.CLOCKWISE)
fork = Motor(Port.D, Direction.CLOCKWISE)
tool = Motor(Port.C, Direction.CLOCKWISE)
drive_base = DriveBase(left, right, 56, 114)
tools = DriveBase(fork, tool, 56, 114)


# The main program starts here.
# alighn at the left most corner but a millimeter and a half to the right
drive_base.use_gyro(True)
tools.use_gyro(False)
drive_base.settings(straight_speed=speed)
drive_base.straight(325)
drive_base.straight(-255)
# flnish flip the rock
drive_base.turn(52)
fork.run_angle(500, 260)
drive_base.straight(440)
fork.run_angle(500, -80)
drive_base.straight(25)
fork.run_angle(500, 5)
drive_base.straight(-499)
# finish expoding seeds
